@module arrangeView  src=arrangeView.lua  loc=738  mode=chunk  self=av
@deps cm, cmgr, facade, am

# Invariants & contracts
  @invariant  av owns arrange-page state — cursor, scroll, selection, paletteSlot; page renders.  @ 4
  @invariant  page builds am and injects it; av owns the ref — all mutations route through av.  @ 5
  @invariant  av speaks no ImGui — modifiers arrive as plain booleans; av works in QN/rows only.  @ 6
  @invariant  cursor/scroll are in-memory module-locals; only beatPerRow persists via cm.  @ 7
  @invariant  cursorRow is integer rows; cursorCol is 0-based track index. qn = row * beatPerRow.  @ 8
  @invariant  gridRows/gridCols set by the page each frame; followViewport runs on every cursor move.  @ 9
  @invariant  av registers arrange-scope command bodies; page owns key bindings and createSlot.  @ 10
  @invariant  selection is a per-session set of take handles; setFocus/focus are single-element.  @ 11
  @invariant  a Shift+arrow band lasts until the first command that isn't a Shift+arrow.  @ 12
  @invariant  paletteSlot is per-session (0..61 or nil) — palette rename/delete; not cursorCol.  @ 13
  @invariant  edit cmds target via actionTargets; off-screen + nothing selected = no-op.  @ 211
  @invariant  drop0..dropZ place a fresh instance at the cursor and advance cm.arrangeAdvanceBy rows.  @ 316
  @invariant  arrangeAdvanceBy0..9 (Ctrl+digit) set the advance step.  @ 317
  @invariant  drop on an empty slot is a no-op; new takes inherit the slot's instance length.  @ 318
  @invariant  drop over a take starting at the cursor overwrites it; drops never stack.  @ 319

# Imports
  @require util = 'util'  @ 15

