  @state FOLLOW_TOP_LEAD = 1  @ 39   -- head lands this many rows below the top after a flip
  @state FOLLOW_BOTTOM_LEAD = 1  @ 40   -- flip once the head reaches this many rows from the bottom
  @state DRAG_EDGE_PX = 5  @ 42   -- end-edge grab band for a resize hit-test
  @state PAGE_ROWS = 16  @ 43   -- PageUp / PageDown cursor step
  @state selectScope = cmgr:scope('arrangeSelect')  @ 150
